INSERT INTO "character" ("key", "kind", "title", "display_name", "gender", "age_profile", "social_status", "address_rule", "voice", "source_ref", "status", "note", "sort") VALUES ('district_karasev', 'fixed_person', 'Геннадий Маркович Карасёв', 'Геннадий Маркович Карасёв', 'male', '30–35 лет.', 'Младший инструктор райкома.', 'С председателем рабочее уважительное «вы»; без фамильярности.', 'Бодро, с газетными оборотами; за официальной речью живой человек.', 'manual/characters/district-faces.md#объяснение-провала-району', 'draft', NULL, 32);
INSERT INTO "character" ("key", "kind", "title", "display_name", "gender", "age_profile", "social_status", "address_rule", "voice", "source_ref", "status", "note", "sort") VALUES ('district_korenev', 'fixed_person', 'Игнат Захарович Коренев', 'Игнат Захарович Коренев', 'male', 'Старше среднего возраста.', 'Секретарь райкома.', 'С председателем рабочее уважительное «вы»; без фамильярности.', 'Тихо, коротко, вместо вывода задаёт вопрос.', 'manual/characters/district-faces.md#объяснение-провала-району', 'draft', NULL, 30);
INSERT INTO "character" ("key", "kind", "title", "display_name", "gender", "age_profile", "social_status", "address_rule", "voice", "source_ref", "status", "note", "sort") VALUES ('district_polushkina', 'fixed_person', 'Зоя Викторовна Полушкина', 'Зоя Викторовна Полушкина', 'female', 'Молодая, недавно после учёбы.', 'Младшая ревизор финуправления.', 'С председателем рабочее уважительное «вы»; без фамильярности.', 'По-писаному и добросовестно; опирается на форму и инструкцию.', 'manual/characters/district-faces.md#объяснение-провала-району', 'draft', NULL, 34);
INSERT INTO "character" ("key", "kind", "title", "display_name", "gender", "age_profile", "social_status", "address_rule", "voice", "source_ref", "status", "note", "sort") VALUES ('district_stozharov', 'fixed_person', 'Роман Трофимович Стожаров', 'Роман Трофимович Стожаров', 'male', 'Старше среднего возраста.', 'Старший инструктор райкома.', 'С председателем рабочее уважительное «вы»; без фамильярности.', 'Негромко и вежливо; знает сельскую работу, слушает прежде ответа.', 'manual/characters/district-faces.md#объяснение-провала-району', 'draft', NULL, 31);
INSERT INTO "character" ("key", "kind", "title", "display_name", "gender", "age_profile", "social_status", "address_rule", "voice", "source_ref", "status", "note", "sort") VALUES ('district_zhernova', 'fixed_person', 'Серафима Прокофьевна Жернова', 'Серафима Прокофьевна Жернова', 'female', 'Пожилая.', 'Старшая ревизор финуправления.', 'С председателем рабочее уважительное «вы»; без фамильярности.', 'Немногословна; точные вопросы и сухие ответы.', 'manual/characters/district-faces.md#объяснение-провала-району', 'draft', NULL, 33);
INSERT INTO "character" ("key", "kind", "title", "display_name", "gender", "age_profile", "social_status", "address_rule", "voice", "source_ref", "status", "note", "sort") VALUES ('egor_panteleev', 'fixed_person', 'Егор Наумыч Пантелеев', 'Егор Наумыч Пантелеев', 'male', 'Немолод; двадцать лет знает жителей поимённо.', 'Участковый; соседняя по отношению к колхозу власть.', 'С председателем — рабочее «вы»; сближение делает речь суше, а не фамильярнее.', 'Короткая фраза после наблюдения; бумага — конкретный предмет; сначала разговор, затем протокол.', 'manual/characters/panteleev.md', 'approved', NULL, 10);
INSERT INTO "character" ("key", "kind", "title", "display_name", "gender", "age_profile", "social_status", "address_rule", "voice", "source_ref", "status", "note", "sort") VALUES ('praskovya_ilyinichna', 'fixed_person', 'Прасковья Ильинична', 'Прасковья Ильинична', 'female', 'Взрослая; точный возраст не назначен.', 'Бухгалтер колхоза.', 'К председателю на «вы»; к знакомым может говорить теплее.', 'Сдержанно заботливая; на проводах говорит короче обычного.', 'manual/texts/epoch1-ending-lines.md', 'draft', NULL, 0);
INSERT INTO "character" ("key", "kind", "title", "display_name", "gender", "age_profile", "social_status", "address_rule", "voice", "source_ref", "status", "note", "sort") VALUES ('shibanov', 'fixed_person', 'Шибанов', 'Шибанов', 'male', 'Взрослый; точный возраст не назначен.', 'Завхоз колхоза.', 'Рабочая близость к председателю без фамильярности.', 'Практичный, суховатый; заботу прячет за разговором о бумагах.', 'manual/texts/epoch1-ending-lines.md', 'draft', NULL, 0);
